class TaskBinding{static Object value(long m,long n){return new alternate.Rational(m,n);}static long[]parts(Object x){return new long[]{((alternate.Rational)x).numerator(),((alternate.Rational)x).denominator()};}static Object operation(Object a,Object b,int op){alternate.Rational x=(alternate.Rational)a,y=(alternate.Rational)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}static Object[]array(Object...a){return java.util.Arrays.copyOf(a,a.length,alternate.Rational[].class);}static void transform(Object[]a){alternate.Rational.transform((alternate.Rational[])a);}}
